void app_main(void)
{
    storage_init();
    volt_init();
    
    // Hardware initialization
    pin_set_output(2);
    pin_set_input_pullup(27);
    
    // I2C bus: i2c0 (hw controller 0)
    volt_i2c_init(0, 21, 22, 400000);
    // UART/Serial: gsm_uart (port 1)
    volt_uart_init(1, 17, 16, 9600);
    
    // Device: lcd (LCD16x2)
    hd44780_init(&_lcd, 0, 39, 16, 2);
    // Device: accel (ADXL345)
    adxl345_init(&_accel, 0, 83);
    // Device: gyro (ITG3205)
    itg3205_init(&_gyro, 0, 104);
    // Device: gsm (SIM800L)
    sim800l_init(&_gsm, 1);
    
    alert_count = storage_load_int("alert_count", 0);
    
    // Setup
    hd44780_clear(&_lcd);
    hd44780_print(&_lcd, "cabinet-ids");
    log_info("boot", "%s", (snprintf(_volt_strbuf[10], sizeof(_volt_strbuf[10]), "cabinet-ids node, alerts so far: %ld", (long)(alert_count)), _volt_strbuf[10]));
    
    // Start background tasks
    volt_task_entry_t _tasks[] = {
        { sensing_run, &_sensing_t },
        { _rule0_run, &__rule0_t },
        { _rule1_run, &__rule1_t },
        { _rule2_run, &__rule2_t },
        { detector_run, &_detector_t },
    };
    volt_run(_tasks, 5);
}

